const TOC = [
    { id: "docs-overview", label: "Overview" },
    { id: "docs-install", label: "Prepare TypeScript" },
    { id: "docs-delivery", label: "How delivery works" },
    { id: "docs-verify", label: "Verify signatures" },
    { id: "docs-payload", label: "Event payload" },
    { id: "docs-retries", label: "Retries" },
] as const;
const RING = 2 * Math.PI * 9;
const SPRING_RING = { stiffness: 1286.2, damping: 95.71, mass: 1 } as const;
function useActiveHeading(): string {
    const [active, setActive] = useState<string>(TOC[0].id);
    useEffect(() => {
        const update = () => {
            const doc = document.documentElement;
            let next: string = TOC[0].id;
            if (window.scrollY + window.innerHeight >= doc.scrollHeight - 2)
                next = TOC[TOC.length - 1].id;
            else {
                const line = window.innerHeight * 0.3;
                for (const t of TOC) {
                    const el = document.getElementById(t.id);
                    if (el && el.getBoundingClientRect().top <= line)
                        next = t.id;
                }
            }
            setActive(next);
        };
        update();
        window.addEventListener("scroll", update, { passive: true });
        window.addEventListener("resize", update);
        return () => {
            window.removeEventListener("scroll", update);
            window.removeEventListener("resize", update);
        };
    }, []);
    return active;
}
function Ring({ progress }: {
    progress: MotionValue<number>;
}) {
    const target = useTransform(progress, (p) => RING * (1 - p));
    const offset = useSpring(target, SPRING_RING);
    return (<svg viewBox="0 0 22 22" className="art:size-5 art:-rotate-90" aria-hidden="true">
      <circle cx="11" cy="11" r="9" fill="none" strokeWidth="2" className="art:stroke-border"/>
      <motion.circle cx="11" cy="11" r="9" fill="none" strokeWidth="2" strokeLinecap="round" strokeDasharray={String(RING)} className="art:stroke-foreground" strokeDashoffset={offset}/>
    </svg>);
}
